    events = context.get('events', [])
    count = 0
    status = 'open'
    pending = []

    def feed(bs):
        nonlocal count, status, pending
        if status != 'open':
            return
        combined = pending + list(bs)
        n = len(combined)
        i = 0
        total = 0
        while i < n:
            b = combined[i]
            if b < 128:
                i += 1
                total += 1
            elif b < 192:
                status = 'error'
                pending = []
                return
            elif b < 224:
                if i + 1 >= n:
                    break
                if combined[i + 1] < 128 or combined[i + 1] > 191:
                    status = 'error'
                    pending = []
                    return
                i += 2
                total += 1
            elif b < 240:
                if i + 1 >= n:
                    break
                if combined[i + 1] < 128 or combined[i + 1] > 191:
                    status = 'error'
                    pending = []
                    return
                if i + 2 >= n:
                    break
                if combined[i + 2] < 128 or combined[i + 2] > 191:
                    status = 'error'
                    pending = []
                    return
                if b == 224 and combined[i + 1] < 160:
                    status = 'error'
                    pending = []
                    return
                if b == 237 and combined[i + 1] > 159:
                    status = 'error'
                    pending = []
                    return
                i += 3
                total += 1
            elif b < 248:
                if i + 1 >= n:
                    break
                if combined[i + 1] < 128 or combined[i + 1] > 191:
                    status = 'error'
                    pending = []
                    return
                if i + 2 >= n:
                    break
                if combined[i + 2] < 128 or combined[i + 2] > 191:
                    status = 'error'
                    pending = []
                    return
                if i + 3 >= n:
                    break
                if combined[i + 3] < 128 or combined[i + 3] > 191:
                    status = 'error'
                    pending = []
                    return
                if b == 240 and combined[i + 1] < 144:
                    status = 'error'
                    pending = []
                    return
                if b == 244 and combined[i + 1] > 143:
                    status = 'error'
                    pending = []
                    return
                i += 4
                total += 1
            else:
                status = 'error'
                pending = []
                return
        count += total
        pending = combined[i:]

    def finish():
        nonlocal status, pending
        if status != 'open':
            return
        if len(pending) == 0:
            status = 'finished'
