            status = 'error'
            pending = []

    def reset():
        nonlocal count, status, pending
        count = 0
        status = 'open'
        pending = []

    for event in events:
        op = event.get('op')
        if op == 'feed':
            feed(event.get('bytes', []))
        elif op == 'finish':
